import{_ as t,o as n,c as a,a2 as o}from"./chunks/framework.CDU0sSpB.js";const m=JSON.parse('{"title":"Documentation Map","description":"Hearth documentation structure, recommended reading order, maintenance rules, and release boundary.","frontmatter":{"title":"Documentation Map","description":"Hearth documentation structure, recommended reading order, maintenance rules, and release boundary.","outline":[2]},"headers":[],"relativePath":"en/reference/source-map.md","filePath":"en/reference/source-map.md","lastUpdated":1793890227000}'),i={name:"en/reference/source-map.md"};function r(d,e,s,l,h,c){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="documentation-map" tabindex="-1">Documentation Map <a class="header-anchor" href="#documentation-map" aria-label="Permalink to &quot;Documentation Map&quot;">​</a></h1><p class="lead">All formal documentation lives under `docs/`, and the repository and published site use the same content. Chinese is the default path; English uses the same structure. When you cannot find a kind of information, start here to decide which section to read.</p><h2 id="documentation-map-1" tabindex="-1">Documentation Map <a class="header-anchor" href="#documentation-map-1" aria-label="Permalink to &quot;Documentation Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Content</th><th>Entry</th></tr></thead><tbody><tr><td>Design</td><td>One overall design and nine parallel module notes, including technology choices</td><td><a href="/hearth-os/en/design/">Overall Design</a></td></tr><tr><td>Delivery</td><td>Six phases, 24 small stages, and the MVP position</td><td><a href="/hearth-os/en/delivery/">Delivery Route</a></td></tr><tr><td>Development Log</td><td>One daily summary and commit details</td><td><a href="/hearth-os/en/log/day-03.html">Day03</a></td></tr><tr><td>Appendix</td><td>Engineering, risk, decisions, build boundaries, terminology, checklists, and maintenance</td><td><a href="/hearth-os/en/reference/">Appendix</a></td></tr><tr><td>Site entry</td><td>Home page and language switch</td><td><a href="/hearth-os/en/">Home</a></td></tr></tbody></table><p>The nine design modules are Entrances and Experience, Tasks and Durable Execution, Control and Authority, Executors and Routing, Approvals and External Effects, Runtime and Safety, Memory and Capability Evolution, Evaluation and Cost, and Multi-device and Long-running Operation. They are peers, not a code-directory map.</p><p>For a first read, follow &quot;why&quot;, then &quot;what comes first&quot;, then &quot;how to implement&quot;:</p><ol><li>Read the <a href="/hearth-os/en/design/">overall design</a> for positioning, task path, technology choices, and module boundaries;</li><li>Read the nine modules in any order as needed;</li><li>Read the <a href="/hearth-os/en/delivery/">delivery route</a> for the six phases and the MVP position;</li><li>Before implementation, read <a href="/hearth-os/en/reference/engineering.html">Engineering</a>, <a href="/hearth-os/en/reference/decisions.html">Key Decisions</a>, and <a href="/hearth-os/en/reference/risks.html">Risks and Stop Conditions</a>.</li></ol><p>To decide quickly whether the project is worth more time, read the positioning section in the overall design and the phase overview in the delivery route. Read the engineering appendix and default checklists only when implementation begins.</p><h2 id="maintenance-and-release-rules" tabindex="-1">Maintenance and Release Rules <a class="header-anchor" href="#maintenance-and-release-rules" aria-label="Permalink to &quot;Maintenance and Release Rules&quot;">​</a></h2><ol><li>Change Chinese first and confirm conclusions, boundaries, and links; update the English mirror in the same commit.</li><li>After changing design or delivery, check the appendix, navigation, sidebar, home page, and language switch.</li><li>Do not introduce code paths, internal class names, or implementation examples into design pages; put engineering constraints in the appendix.</li><li>Delete old pages directly; do not keep redirects or duplicate body text. Search the site for old paths and remove dead links.</li><li>Run <code>npm run docs:build</code>, then check internal links, mobile width, and search entries.</li><li>Do not use &quot;should&quot; or &quot;later&quot; to hide an undecided question. Mark unverified content as a hypothesis.</li></ol><p>The documentation describes product specifications, design judgments, and a development plan; it does not mean the product has shipped. Development logs record daily work and commits, not release notes. Maintain a formal version number and release notes only after an installable version exists.</p><p>The published site should match the build from <code>docs/</code>. After every deployment, verify that old addresses are gone, every bilingual page resolves, and the sidebar and home entries point to the new structure.</p>',12)])])}const p=t(i,[["render",r]]);export{m as __pageData,p as default};
